import { test } from "node:test";
import assert from "node:assert/strict";
import { searchHotels } from "../src/hotels/search.js";
import { callWithTimeout, TimeoutError } from "../src/hotels/timeout.js";
import { instantSupplier, failingSupplier, hangingSupplier } from "../src/hotels/suppliers.js";

// Fails the test instead of hanging it if the promise never settles.
function within(ms, promise, what) {
  let timer;
  const guard = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${what} still pending after ${ms}ms: the timeout never fired`)), ms);
  });
  return Promise.race([promise, guard]).finally(() => clearTimeout(timer));
}

const query = { city: "Lisbon", nights: 2 };
const ritz = { hotelId: "ritz", pricePerNight: 300 };
const casa = { hotelId: "casa", pricePerNight: 90 };

test("all suppliers answering: offers are merged, cheapest first", async () => {
  const a = instantSupplier("alpha", [ritz, casa]);
  const b = instantSupplier("beta", [{ hotelId: "casa", pricePerNight: 80 }]);
  const res = await searchHotels([a, b], query, { timeoutMs: 50 });
  assert.deepEqual(
    res.offers.map((o) => [o.hotelId, o.supplier, o.total]),
    [
      ["casa", "beta", 160],
      ["ritz", "alpha", 600],
    ],
  );
  assert.deepEqual(res.skipped, []);
});

test("a failing supplier is skipped with reason 'error'", async () => {
  const res = await searchHotels([instantSupplier("alpha", [ritz]), failingSupplier("beta")], query, { timeoutMs: 50 });
  assert.equal(res.offers.length, 1);
  assert.deepEqual(res.skipped, [{ supplier: "beta", reason: "error" }]);
});

test("a hanging supplier is skipped with reason 'timeout' and the rest still answer", async () => {
  const slow = hangingSupplier("gamma");
  const res = await within(1000, searchHotels([instantSupplier("alpha", [ritz]), slow], query, { timeoutMs: 30 }), "searchHotels");
  console.log("skipped:", res.skipped, "offers:", res.offers.map((o) => o.hotelId));
  assert.deepEqual(res.skipped, [{ supplier: "gamma", reason: "timeout" }]);
  assert.deepEqual(res.offers.map((o) => o.hotelId), ["ritz"]);
});

test("the hanging supplier's request is cancelled when the timeout fires", async () => {
  const slow = hangingSupplier("gamma");
  await within(1000, searchHotels([slow], query, { timeoutMs: 20 }), "searchHotels").catch(() => {});
  assert.equal(slow.started, true);
  assert.equal(slow.aborted, true, "the supplier call should have received an abort signal");
});

test("callWithTimeout rejects with a TimeoutError carrying the limit", async () => {
  const err = await within(1000, callWithTimeout((signal) => new Promise((_, reject) => signal?.addEventListener("abort", () => reject(signal.reason))), 25), "callWithTimeout").then(
    () => null,
    (e) => e,
  );
  assert.ok(err instanceof TimeoutError, `expected TimeoutError, got ${err}`);
  assert.equal(err.timeoutMs, 25);
});

test("callWithTimeout returns the value of a fast call", async () => {
  assert.equal(await callWithTimeout(async () => 42, 1000), 42);
});

test("callWithTimeout passes through the callee's own error", async () => {
  await assert.rejects(
    callWithTimeout(async () => {
      throw new RangeError("bad date range");
    }, 1000),
    RangeError,
  );
});
